// What an API upload writes (INT-02 A2, ADR-0052 §2): the server's twin of
// `src-tauri/src/runs/import.rs::plan`, the desktop's one persister of
// Pharos Run JSON. Pure: a parsed document and a shard id in, the shard and
// result documents out, byte for byte what the desktop would write and sync
// for the same file (`tests/fixtures/api-import-interop.json`, generated by
// the Rust side, holds them equal).
//
// No linking here: an imported result stores only what its report said, and
// its case, revision, item, flow, row and configuration are derived when read
// (ADR-0013 «Vínculo derivado», `domain/resultLink.ts`).
//
// The id functions come from `@pharos/formats` as a parameter, not a static
// import: the server process must boot without loading the package (its
// own imports, uuid and zod, resolve only where its dependencies are
// installed; the upload loads it when it runs, as the parser does).
import { createHash } from "node:crypto";
import { AppError } from "../auth/errors.js";

type Json = Record<string, unknown>;

/** Formats a shard may come from: the desktop's (`import.rs::FORMATS`) plus
 *  ING-06's, whose findings and metrics F2 stores (ADR-0053); until then their
 *  shard has no results and the findings stay in the raw report. */
export const IMPORT_FORMATS = [
  "cucumber_messages",
  "ctrf",
  "junit",
  "playwright_json",
  "pharos_run_json",
  "sarif",
  "axe",
  "k6",
  // ING-07 (Pharos Run JSON 1.1.0).
  "allure",
  "trx",
  "xcresult",
] as const;

export const MAX_IMPORT_RESULTS = 20_000;
export const MAX_ERROR_MESSAGE = 8_000;
export const MAX_ERROR_TRACE = 64_000;
export const MAX_STEP_TEXT = 4_000;
export const MAX_LABEL = 200;
export const MAX_ATTRIBUTES = 16 * 1024;
export const MAX_RESULT_DOC = 1024 * 1024;
export const MAX_TITLE = 500;
export const MAX_TEST_KEY = 2000;
export const MAX_STEPS = 5000;

const RESULT_STATUSES = ["passed", "failed", "blocked", "skipped", "other"];
/** Keys of a result with their own place (`import.rs::KNOWN_KEYS`). */
const KNOWN_KEYS = ["shardRef", "retries", "type", "device"];
/** Keys the desktop's `DocResult` reads; any other key goes to attributes. */
const RESULT_FIELDS = new Set([
  "name",
  "status",
  "rawStatus",
  "testKey",
  "tags",
  "attempt",
  "configurationLabel",
  "browser",
  "externalId",
  "caseKey",
  "exampleRow",
  "exampleValues",
  "duration",
  "startedAt",
  "finishedAt",
  "start",
  "stop",
  "message",
  "trace",
  "flaky",
  "suite",
  "filePath",
  "steps",
  "attachments",
  "attributes",
]);
const KEYWORDS = ["Given", "When", "Then", "And", "But", "*", "Dado", "Dada", "Cuando", "Entonces", "Y", "Pero"];

export const importError = (code: string, message: string) => new AppError(422, "invalid_report", message, { reason: code });

// ---- helpers (the desktop's, one by one) ---------------------------------------

const utf16 = (s: string) => s.length;

/** `s` cut to `max` UTF-16 units (as zod counts), ending in "…" when cut. */
export function clip(s: string, max: number): [string, boolean] {
  if (utf16(s) <= max) return [s, false];
  let out = "";
  let units = 0;
  for (const ch of s) {
    const n = ch.length;
    if (units + n > Math.max(0, max - 1)) break;
    units += n;
    out += ch;
  }
  return [`${out}…`, true];
}

/** A `test_key` within the limit: a longer one keeps its start and a hash of
 *  the whole. */
function boundedKey(key: string): [string, boolean] {
  if (utf16(key) <= MAX_TEST_KEY) return [key, false];
  const hash = createHash("sha256").update(key, "utf8").digest("hex");
  return [`${clip(key, MAX_TEST_KEY - 20)[0]}#${hash.slice(0, 16)}`, true];
}

/** A non-empty trimmed text, or null (`runs::text`). */
export const text = (v: unknown): string | null => (typeof v === "string" && v.trim() ? v.trim() : null);

/** An ISO time from a document time (text, or epoch ms as CTRF sends it). */
function timeOf(v: unknown): string | null {
  if (typeof v === "string") return v.trim() ? v.trim() : null;
  if (typeof v === "number" && Number.isFinite(v) && v >= 0) return new Date(Math.trunc(v)).toISOString();
  return null;
}

function statusOf(s: string): string {
  if (s === "pending") return "skipped";
  return RESULT_STATUSES.includes(s) ? s : "other";
}

function splitKeyword(keyword: unknown, t: string): [string | null, string] {
  const k = typeof keyword === "string" ? keyword.trim() : "";
  if (k) return [k, t];
  for (const kw of KEYWORDS) if (t.startsWith(`${kw} `)) return [kw, t.slice(kw.length + 1)];
  return [null, t];
}

function suiteOf(r: Json): string[] {
  const s = r.suite;
  if (Array.isArray(s)) return s.filter((x): x is string => typeof x === "string");
  if (typeof s === "string") return s.split(" > ");
  return [];
}

const nonNegRound = (v: unknown): number | null =>
  typeof v === "number" && Number.isFinite(v) && v >= 0 ? Math.round(v) : null;
const intOrNull = (v: unknown): number | null => (typeof v === "number" && Number.isInteger(v) ? v : null);
const obj = (v: unknown): Json => (v && typeof v === "object" && !Array.isArray(v) ? (v as Json) : {});
const arr = (v: unknown): unknown[] => (Array.isArray(v) ? v : []);
const bytes = (v: unknown) => Buffer.byteLength(JSON.stringify(v), "utf8");

// ---- the plan ----------------------------------------------------------------

export interface ImportWarning {
  code: string;
  testKey: string | null;
  detail: string | null;
}

export interface PlannedStep {
  id: string;
  position: number;
  stepId: null;
  keyword: string | null;
  text: string;
  status: string;
  actual: string | null;
  durationMs: number | null;
  gherkinLine: number | null;
}

/** One result as it is written: the content keys of its document. */
export interface PlannedResult {
  id: string;
  testKey: string;
  configurationLabel: string | null;
  attempt: number;
  status: string;
  rawStatus: string | null;
  durationMs: number | null;
  startedAt: string | null;
  finishedAt: string | null;
  errorMessage: string | null;
  errorTrace: string | null;
  externalId: string | null;
  exampleRow: number | null;
  exampleValues: unknown;
  caseKey: string | null;
  attributes: Json;
  steps: PlannedStep[];
  /** Refs of the document's attachments, for the result and its steps. */
  attachmentRefs: string[];
  stepAttachmentRefs: [number, string][];
}

export interface ImportPlan {
  executedBy: string;
  format: string;
  formatVersion: string | null;
  shardIndex: number | null;
  shardTotal: number | null;
  normalizerVersion: number;
  results: PlannedResult[];
  warnings: ImportWarning[];
}

/** The run fields a new run takes from the document (`import.rs::commit`). */
export function runFieldsOf(doc: Json) {
  const run = obj(doc.run);
  return {
    title: text(run.title),
    sourceTool: text(run.sourceTool),
    sourceToolVersion: text(run.sourceToolVersion),
    environment: text(run.environment),
    build: text(run.build),
    commitSha: text(run.commitSha),
    branch: text(run.branch),
    repositoryUrl: text(run.repositoryUrl),
    ciUrl: text(run.ciUrl),
    dataset: text(run.dataset),
    context: run.context && typeof run.context === "object" && !Array.isArray(run.context) ? (run.context as Json) : null,
    // A report that gives only its end starts then too, not at the import:
    // a run never starts after it finishes (FIX-42, as `import.rs`).
    startedAt: timeOf(run.startedAt) ?? timeOf(run.finishedAt),
    finishedAt: timeOf(run.finishedAt),
  };
}

/** The normalizer version of a document (0 when it does not say). */
export function normalizerOf(doc: Json): number {
  const v = obj(arr(doc.shards)[0]).normalizerVersion;
  return typeof v === "number" && Number.isInteger(v) && v > 0 ? v : 0;
}

/** Checks the version and the size of a document (`import.rs::parse_doc`). */
export function checkDoc(doc: Json): void {
  const version = typeof doc.schemaVersion === "string" ? doc.schemaVersion : "";
  if (version.split(".")[0] !== "1")
    throw importError("unsupported-version", `Pharos Run JSON ${version}; this server reads 1.x`);
  if (arr(doc.results).length > MAX_IMPORT_RESULTS)
    throw importError("too-large", `at most ${MAX_IMPORT_RESULTS} results per import`);
}

/** What will be written for `doc` into the shard `shardId`
 *  (`import.rs::plan`, without the link). */
/** The deterministic ids of an import (`@pharos/formats`, `ids.ts`). */
export interface ResultIds {
  importedResultId: (shard: string, testKey: string, label: string | null | undefined, attempt: number) => string;
  importedStepResultId: (resultId: string, position: number) => string;
}

export function planImport(doc: Json, shardId: string, ids: ResultIds): ImportPlan {
  const { importedResultId, importedStepResultId } = ids;
  const shard = obj(arr(doc.shards)[0]);
  const format = text(shard.sourceFormat) ?? "pharos_run_json";
  if (!(IMPORT_FORMATS as readonly string[]).includes(format))
    throw new AppError(422, "unsupported_format", `This server does not import ${format} yet.`, { format });
  const shardIndex = intOrNull(shard.shardIndex);
  const shardTotal = intOrNull(shard.shardTotal);
  const shardOk =
    (shardIndex === null && shardTotal === null) ||
    (shardIndex !== null && shardTotal !== null && shardIndex >= 1 && shardIndex <= shardTotal);
  if (!shardOk) throw importError("invalid-shard", "the index must be between 1 and the total");
  const known = new Set(
    arr(doc.attachments)
      .map((a) => obj(a).ref)
      .filter((r): r is string => typeof r === "string"),
  );
  const warnings: ImportWarning[] = [];
  const seen = new Map<string, number>();
  const idsSeen = new Set<string>();
  const out: PlannedResult[] = [];
  for (const raw of arr(doc.results)) {
    const r = obj(raw);
    const rawKey = (typeof r.testKey === "string" ? r.testKey : "").trim();
    const name = typeof r.name === "string" ? r.name : "";
    if (!rawKey) throw importError("test-key-required", name);
    const bounded = boundedKey(rawKey);
    let key = bounded[0];
    const long = bounded[1];
    if (long) warnings.push({ code: "key-too-long", testKey: key, detail: null });
    const labelText = text(r.configurationLabel) ?? text(r.browser);
    const label = labelText === null ? null : clip(labelText, MAX_LABEL)[0];
    const attempt = Math.max(0, intOrNull(r.attempt) ?? 0);
    let id = importedResultId(shardId, key, label, attempt);
    if (idsSeen.has(id)) {
      const dupKey = `${key}\u0000${label ?? ""}\u0000${attempt}`;
      let n = seen.get(dupKey) ?? 1;
      for (;;) {
        n += 1;
        const candidate = boundedKey(`${key} #${n}`)[0];
        const cid = importedResultId(shardId, candidate, label, attempt);
        if (!idsSeen.has(cid)) {
          idsSeen.add(cid);
          warnings.push({ code: "duplicate-test", testKey: candidate, detail: null });
          key = candidate;
          id = cid;
          break;
        }
      }
      seen.set(dupKey, n);
    } else {
      idsSeen.add(id);
    }
    const stepsIn = arr(r.steps).map(obj);
    if (stepsIn.length > MAX_STEPS) throw importError("steps-too-many", `at most ${MAX_STEPS} steps (${key})`);
    let truncated = false;
    const steps: PlannedStep[] = [];
    const stepAttachmentRefs: [number, string][] = [];
    stepsIn.forEach((s, i) => {
      const t0 = typeof s.text === "string" ? s.text : typeof s.name === "string" ? s.name : "";
      const [keyword, stepText] = splitKeyword(s.keyword, t0);
      const [t, a] = clip(stepText, MAX_STEP_TEXT);
      const actual = typeof s.actual === "string" ? clip(s.actual, MAX_STEP_TEXT) : null;
      truncated ||= a || (actual?.[1] ?? false);
      steps.push({
        id: importedStepResultId(id, i),
        position: i,
        stepId: null,
        keyword,
        text: t,
        status: statusOf(typeof s.status === "string" ? s.status : ""),
        actual: actual ? actual[0] : null,
        durationMs: nonNegRound(s.durationMs),
        gherkinLine: intOrNull(s.gherkinLine),
      });
      for (const ref of arr(s.attachments)) if (typeof ref === "string" && known.has(ref)) stepAttachmentRefs.push([i, ref]);
    });
    const message = typeof r.message === "string" ? clip(r.message, MAX_ERROR_MESSAGE) : null;
    const trace = typeof r.trace === "string" ? clip(r.trace, MAX_ERROR_TRACE) : null;
    truncated ||= (message?.[1] ?? false) || (trace?.[1] ?? false);
    // attributes: the document's own (without tags and suite), what has no
    // column (name, tags, file, suite), the tool's flaky and the unknown keys.
    const attrs: Json = { ...obj(r.attributes) };
    delete attrs.tags;
    delete attrs.suite;
    attrs.name = clip(name, MAX_TITLE)[0];
    const tags = arr(r.tags).filter((x): x is string => typeof x === "string");
    if (tags.length) attrs.tags = tags;
    if (typeof r.filePath === "string") attrs.filePath = r.filePath;
    const suite = suiteOf(r);
    if (suite.length) attrs.suite = suite;
    if (typeof r.flaky === "boolean") attrs.flaky = r.flaky;
    for (const [k, v] of Object.entries(r)) {
      if (RESULT_FIELDS.has(k) || KNOWN_KEYS.includes(k) || k in attrs) continue;
      attrs[k] = v;
    }
    let attributes: Json = attrs;
    if (bytes(attributes) > MAX_ATTRIBUTES) {
      attributes = {
        name: attrs.name ?? null,
        flaky: attrs.flaky ?? null,
        tags: attrs.tags ?? null,
        suite: attrs.suite ?? null,
        attributesTruncated: true,
      };
      truncated = true;
    }
    const caseKey = text(r.caseKey);
    const externalId = text(r.externalId);
    const planned: PlannedResult = {
      id,
      testKey: key,
      configurationLabel: label,
      attempt,
      status: statusOf(typeof r.status === "string" ? r.status : ""),
      rawStatus: text(r.rawStatus) ?? (r.status === "pending" ? "pending" : null),
      durationMs: nonNegRound(r.duration),
      startedAt: timeOf(r.startedAt ?? r.start),
      finishedAt: timeOf(r.finishedAt ?? r.stop),
      errorMessage: message ? message[0] : null,
      errorTrace: trace ? trace[0] : null,
      externalId: externalId === null ? null : clip(externalId, MAX_LABEL)[0],
      exampleRow: intOrNull(r.exampleRow),
      exampleValues: r.exampleValues === undefined || r.exampleValues === null ? null : r.exampleValues,
      caseKey: caseKey === null ? null : clip(caseKey, MAX_LABEL)[0],
      attributes,
      steps,
      attachmentRefs: arr(r.attachments).filter((x): x is string => typeof x === "string" && known.has(x)),
      stepAttachmentRefs,
    };
    if (docSize(planned) > MAX_RESULT_DOC) {
      for (const s of planned.steps) s.actual = null;
      truncated = true;
    }
    if (docSize(planned) > MAX_RESULT_DOC) {
      warnings.push({ code: "result-too-large", testKey: key, detail: null });
      continue;
    }
    if (truncated) warnings.push({ code: "text-truncated", testKey: key, detail: null });
    out.push(planned);
  }
  const run = obj(doc.run);
  const executedBy = `tool:${text(run.sourceTool) ?? format}`;
  const formatVersion = text(shard.formatVersion);
  return {
    executedBy: clip(executedBy, MAX_LABEL)[0],
    format,
    formatVersion: typeof shard.formatVersion === "string" ? clip(shard.formatVersion, MAX_LABEL)[0] : formatVersion,
    shardIndex,
    shardTotal,
    normalizerVersion: normalizerOf(doc),
    results: out,
    warnings,
  };
}

/** Bytes of the result document as pushed (`import.rs::doc_size`). */
function docSize(p: PlannedResult): number {
  return (
    2048 +
    bytes({
      testKey: p.testKey,
      configurationLabel: p.configurationLabel,
      status: p.status,
      rawStatus: p.rawStatus,
      errorMessage: p.errorMessage,
      errorTrace: p.errorTrace,
      externalId: p.externalId,
      exampleValues: p.exampleValues === null ? null : JSON.stringify(p.exampleValues),
      attributes: p.attributes,
      steps: p.steps,
    })
  );
}

/** The final status of each test, counted (`import.rs::statuses_of`). */
export function statusCounts(results: PlannedResult[]): Record<string, number> {
  const finals = new Map<string, [number, string]>();
  for (const r of results) {
    const k = `${r.testKey}\u0000${r.configurationLabel ?? ""}`;
    const e = finals.get(k);
    if (!e || r.attempt >= e[0]) finals.set(k, [r.attempt, r.status]);
  }
  const counts: Record<string, number> = { passed: 0, failed: 0, blocked: 0, skipped: 0, other: 0 };
  for (const [, s] of finals.values()) counts[s] = (counts[s] ?? 0) + 1;
  return counts;
}

/** The documents an import writes for a planned result. */
export function resultPayload(
  r: PlannedResult,
  ctx: { projectId: string; runId: string; shardId: string; executedBy: string; userId: string; at: string; hlc: string },
): Json {
  return {
    id: r.id,
    workspaceId: "local",
    projectId: ctx.projectId,
    runId: ctx.runId,
    shardId: ctx.shardId,
    runItemId: null,
    testKey: r.testKey,
    testCaseId: null,
    testCaseRevisionId: null,
    caseRevision: null,
    caseKey: r.caseKey,
    flowId: null,
    exampleRowId: null,
    exampleRow: r.exampleRow,
    exampleValues: r.exampleValues,
    configurationId: null,
    configurationLabel: r.configurationLabel,
    attempt: r.attempt,
    status: r.status,
    rawStatus: r.rawStatus,
    durationMs: r.durationMs,
    startedAt: r.startedAt,
    finishedAt: r.finishedAt,
    errorMessage: r.errorMessage,
    errorTrace: r.errorTrace,
    executedBy: ctx.executedBy,
    externalId: r.externalId,
    attributes: r.attributes,
    createdBy: ctx.userId,
    createdAt: ctx.at,
    hlc: ctx.hlc,
    steps: r.steps,
  };
}

// ---- findings and metrics (ING-06, ADR-0053; A2b) ---------------------------------
//
// The twin of `src-tauri/src/runs/findings.rs::plan`: the document's
// `findings[]` and `metrics[]` checked and shaped for a shard, the same ids
// (`findingId`, `metricId`), cuts and payloads the desktop writes and syncs.

export const MAX_FINDINGS = 20_000;
export const MAX_METRICS = 5_000;
const MAX_HTML = 1_000;
const MAX_TEXT = 1_000;
export const SEVERITIES = ["critical", "high", "medium", "low", "info"] as const;

/** A trimmed, non-empty text of `v[k]`, cut to `max`, or null. */
function optText(v: Json, k: string, max: number): string | null {
  const s = typeof v[k] === "string" ? (v[k] as string).trim() : "";
  return s ? clip(s, max)[0] : null;
}

/** An object as stored: whole within the attribute limit; over it, only its
 *  `tool` and `truncated: true` (`findings.rs::object_text`). */
function objectStored(v: unknown): [Json, boolean] {
  const o = obj(v);
  if (bytes(o) <= MAX_ATTRIBUTES) return [o, false];
  const kept: Json = {};
  if ("tool" in o) kept.tool = o.tool;
  kept.truncated = true;
  return [kept, true];
}

/** The attributes of a finding or a metric with its document's `caseKey`
 *  (trimmed, clipped to MAX_TEXT) kept as `attributes.caseKey` unless they
 *  already name one (`findings.rs::with_case_key`, F5): the case link uses
 *  it. */
function withCaseKey(entry: Json): Json {
  const attributes = { ...obj(entry.attributes) };
  const key = typeof entry.caseKey === "string" ? entry.caseKey.trim() : "";
  if (key && !("caseKey" in attributes)) attributes.caseKey = clip(key, MAX_TEXT)[0];
  return attributes;
}

export interface PlannedFinding {
  id: string;
  ruleId: string;
  ruleName: string | null;
  severity: (typeof SEVERITIES)[number];
  rawSeverity: string | null;
  message: string;
  location: Json;
  fingerprint: string;
  standardRefs: string[];
  helpUri: string | null;
  attributes: Json;
}

export interface PlannedMetric {
  id: string;
  name: string;
  aggregation: string | null;
  scope: string | null;
  value: number;
  unit: string | null;
  threshold: string | null;
  passed: boolean | null;
  attributes: Json;
}

export interface FindingsPlan {
  findings: PlannedFinding[];
  metrics: PlannedMetric[];
  warnings: ImportWarning[];
}

/** Checks and shapes `findings[]` and `metrics[]` for a shard. A finding
 *  needs its rule, severity, message and fingerprint; a metric its name and a
 *  finite value; anything else is `invalid_report`. */
export function planFindings(doc: Json, shardId: string, ids: {
  findingId: (shard: string, fingerprint: string, n: number) => string;
  metricId: (shard: string, name: string, aggregation: string | null, scope: string | null) => string;
}): FindingsPlan {
  const findings = arr(doc.findings);
  const metrics = arr(doc.metrics);
  if (findings.length > MAX_FINDINGS) throw importError("too-large", `at most ${MAX_FINDINGS} findings per import`);
  if (metrics.length > MAX_METRICS) throw importError("too-large", `at most ${MAX_METRICS} metrics per import`);
  const out: FindingsPlan = { findings: [], metrics: [], warnings: [] };
  let cut = 0;
  const seen = new Map<string, number>();
  findings.forEach((raw, i) => {
    const f = obj(raw);
    const bad = (what: string) => importError("invalid-report", `findings.${i}.${what}`);
    const ruleId = optText(f, "ruleId", MAX_TEXT);
    if (!ruleId) throw bad("ruleId");
    const severity = f.severity;
    if (typeof severity !== "string" || !(SEVERITIES as readonly string[]).includes(severity)) throw bad("severity");
    const messageRaw = typeof f.message === "string" && f.message.trim() ? f.message : null;
    if (!messageRaw) throw bad("message");
    const [message, cutMessage] = clip(messageRaw, MAX_ERROR_MESSAGE);
    const fingerprint = optText(f, "fingerprint", MAX_TEXT);
    if (!fingerprint) throw bad("fingerprint");
    const location0: Json = { ...obj(f.location) };
    let cutHtml = false;
    if (typeof location0.html === "string") {
      const [h, c] = clip(location0.html, MAX_HTML);
      cutHtml = c;
      location0.html = h;
    }
    const [location, cutLocation] = objectStored(location0);
    const [attributes, cutAttributes] = objectStored(withCaseKey(f));
    const standardRefs = arr(f.standardRefs)
      .filter((s): s is string => typeof s === "string")
      .map((s) => clip(s, MAX_TEXT)[0]);
    if (cutMessage || cutHtml || cutLocation || cutAttributes) cut += 1;
    const n = seen.get(fingerprint) ?? 0;
    seen.set(fingerprint, n + 1);
    out.findings.push({
      id: ids.findingId(shardId, fingerprint, n),
      ruleId,
      ruleName: optText(f, "ruleName", MAX_TEXT),
      severity: severity as PlannedFinding["severity"],
      rawSeverity: optText(f, "rawSeverity", MAX_TEXT),
      message,
      location,
      fingerprint,
      standardRefs,
      helpUri: optText(f, "helpUri", MAX_TEXT),
      attributes,
    });
  });
  const metricIds = new Set<string>();
  metrics.forEach((raw, i) => {
    const m = obj(raw);
    const bad = (what: string) => importError("invalid-report", `metrics.${i}.${what}`);
    const name = optText(m, "name", MAX_TEXT);
    if (!name) throw bad("name");
    const value = m.value;
    if (typeof value !== "number" || !Number.isFinite(value)) throw bad("value");
    const aggregation = optText(m, "aggregation", MAX_TEXT);
    const scope = optText(m, "scope", MAX_TEXT);
    const id = ids.metricId(shardId, name, aggregation, scope);
    if (metricIds.has(id)) {
      // The same name, aggregation and scope twice: the first one counts.
      out.warnings.push({ code: "duplicate-metric", testKey: null, detail: name });
      return;
    }
    metricIds.add(id);
    const [attributes, cutAttributes] = objectStored(withCaseKey(m));
    if (cutAttributes) cut += 1;
    out.metrics.push({
      id,
      name,
      aggregation,
      scope,
      value,
      unit: optText(m, "unit", MAX_TEXT),
      threshold: optText(m, "threshold", MAX_TEXT),
      passed: typeof m.passed === "boolean" ? m.passed : null,
      attributes,
    });
  });
  if (cut > 0) out.warnings.push({ code: "text-truncated", testKey: null, detail: String(cut) });
  return out;
}

/** Findings by severity, for the import event (`Planned::severities`). */
export function severityCounts(findings: PlannedFinding[]): Record<string, number> {
  const out: Record<string, number> = {};
  for (const s of SEVERITIES) {
    const n = findings.filter((f) => f.severity === s).length;
    if (n > 0) out[s] = n;
  }
  return out;
}

type DocContext = { projectId: string; runId: string; shardId: string; userId: string; at: string; hlc: string };

/** The `finding` document (`findings.rs::finding_payload`). */
export function findingPayload(f: PlannedFinding, ctx: DocContext): Json {
  return {
    id: f.id,
    workspaceId: "local",
    projectId: ctx.projectId,
    runId: ctx.runId,
    shardId: ctx.shardId,
    ruleId: f.ruleId,
    ruleName: f.ruleName,
    severity: f.severity,
    rawSeverity: f.rawSeverity,
    message: f.message,
    location: f.location,
    fingerprint: f.fingerprint,
    standardRefs: f.standardRefs,
    helpUri: f.helpUri,
    attributes: f.attributes,
    createdBy: ctx.userId,
    createdAt: ctx.at,
    hlc: ctx.hlc,
  };
}

/** The `metric` document (`findings.rs::metric_payload`). */
export function metricPayload(m: PlannedMetric, ctx: DocContext): Json {
  return {
    id: m.id,
    workspaceId: "local",
    projectId: ctx.projectId,
    runId: ctx.runId,
    shardId: ctx.shardId,
    name: m.name,
    aggregation: m.aggregation,
    scope: m.scope,
    value: m.value,
    unit: m.unit,
    threshold: m.threshold,
    passed: m.passed,
    attributes: m.attributes,
    createdBy: ctx.userId,
    createdAt: ctx.at,
    hlc: ctx.hlc,
  };
}
